-- Access-control seed for fresh databases, applied after V001. No accounts or demo data are created.
--
-- Roles, permissions and role grants of the SRS Permission Matrix 4.4 (ADR-0015) in their final form,
-- including the staff member, role administration, catalog management, agreement, session and assignment
-- permissions. One permission per matrix row; sign-in and password rows need no permission.
-- "Restricted n" cells are granted here; footnote n limits are enforced by the use case. A permission
-- protects at most one endpoint, named by its HTTP method and the route template declared by the
-- controller; permissions without an endpoint belong to use cases that have no public route yet, and the
-- ones marked "Not in the SRS Permission Matrix 4.4 yet" are additions to the matrix. `module`, `use_cases`
-- and `sensitive` feed the permission catalogue of the role administration screens. Future matrix changes
-- require a new migration.

INSERT INTO public.roles (code, name, description)
VALUES
    ('PATIENT', 'Patient', 'Patient account using the portal for own examinations, reports, prescriptions, appointments and contact details.'),
    ('RECEPTIONIST', 'Receptionist', 'Registers patients, receives outpatients, manages appointments and collects payments.'),
    ('GENERAL_PRACTITIONER', 'General Practitioner', 'Examines outpatients, orders diagnostic services and records diagnoses, conclusions and prescriptions.'),
    ('DIAGNOSTIC_DOCTOR', 'Diagnostic Doctor', 'Performs diagnostic services and records, finalizes, amends and prints diagnostic results.'),
    ('NURSE', 'Nurse', 'Prepares participant examination records, enters batch examination data and issues completed records.'),
    ('CLINIC_MANAGER', 'Clinic Manager', 'Manages organizations, health examination batches, participants, clinic master data and operational reports.'),
    ('ADMINISTRATOR', 'Administrator', 'Manages user accounts, roles and permissions, reviews audit logs and submits national health data.');

